import "server-only";
import manifest from "./image-manifest.json";

type Entry = { width: number; height: number; blurDataURL: string };
const entries: Record<string, Entry | undefined> = manifest;

/**
 * Blur-up placeholder props for a /images source, generated by scripts/optimize-images.mjs.
 * Server-only so the manifest never ships in client JS; client components get
 * `blurDataURL` passed down as a prop instead.
 */
export function blurProps(src: string) {
  const blurDataURL = entries[src]?.blurDataURL;
  return blurDataURL ? { placeholder: "blur" as const, blurDataURL } : {};
}

/** Intrinsic width/height of a /images source, for layouts that size from the image itself. */
export function imageSize(src: string) {
  const entry = entries[src];
  return entry ? { width: entry.width, height: entry.height } : undefined;
}

/** Attach each photo's blur placeholder before handing a list to a client component. */
export function withBlur<T extends { src: string }>(photos: T[]): (T & { blurDataURL?: string })[] {
  return photos.map((p) => ({ ...p, blurDataURL: entries[p.src]?.blurDataURL }));
}
